  1131→export default function TOHaejungUpload({ onSuccess }: Props) {
  1132→  const fileRef = useRef<HTMLInputElement>(null);
  1133→  const [status, setStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  1134→  const [uploading, setUploading] = useState(false);
  1135→
  1136→  const handleUpload = async () => {
  1137→    const file = fileRef.current?.files?.[0];
  1138→    if (!file) {
  1139→      setStatus({ type: 'error', message: '파일을 선택해주세요.' });
  1140→      return;
  1141→    }
  1142→    if (!file.name.endsWith('.xlsx')) {
  1143→      setStatus({ type: 'error', message: '.xlsx 파일만 업로드 가능합니다.' });
  1144→      return;
  1145→    }
  1146→    const confirmed = window.confirm('기존 데이터가 모두 교체됩니다. 계속하시겠습니까?');
  1147→    if (!confirmed) return;
  1148→
  1149→    setUploading(true);
  1150→    setStatus(null);
  1151→    const formData = new FormData();
  1152→    formData.append('file', file);
  1153→    try {
  1154→      const res = await fetch('/api/to-haejung/upload', { method: 'POST', body: formData });
  1155→      const data = await res.json();
  1156→      if (!res.ok) throw new Error(data.error ?? '업로드 실패');
  1157→      setStatus({ type: 'success', message: `${data.count}개 행이 성공적으로 임포트되었습니다.` });
  1158→      if (fileRef.current) fileRef.current.value = '';
  1159→      onSuccess();
  1160→    } catch (err) {
  1161→      setStatus({ type: 'error', message: err instanceof Error ? err.message : '업로드 실패' });
  1162→    } finally {
  1163→      setUploading(false);
  1164→    }
  1165→  };
  1166→
  1167→  return (
  1168→    <div className="space-y-3">
  1169→      <div className="flex items-center gap-3">
  1170→        <input
  1171→          ref={fileRef}
  1172→          type="file"
  1173→          accept=".xlsx"
  1174→          className="block text-sm text-gray-600 file:mr-3 file:py-2 file:px-4 file:rounded file:border-0 file:bg-blue-50 file:text-blue-700 file:cursor-pointer hover:file:bg-blue-100"
  1175→        />
  1176→        <button
  1177→          type="button"
  1178→          onClick={handleUpload}
  1179→          disabled={uploading}
  1180→          className="px-4 py-2 bg-blue-700 text-white text-sm rounded hover:bg-blue-800 disabled:opacity-50"
  1181→        >
  1182→          {uploading ? '업로드 중...' : '업로드'}
  1183→        </button>
  1184→      </div>
  1185→      {status && (
  1186→        <div
  1187→          className={`rounded p-3 text-sm ${
  1188→            status.type === 'success'
  1189→              ? 'bg-green-50 border border-green-200 text-green-800'
  1190→              : 'bg-red-50 border border-red-200 text-red-700'
  1191→          }`}
  1192→        >
  1193→          {status.message}
  1194→        </div>
  1195→      )}
  1196→    </div>
  1197→  );
  1198→}
